import{_ as n,o as s,c as a,a2 as o}from"./chunks/framework.Di-jvWLj.js";const u=JSON.parse('{"title":"Cron Scheduling","description":"","frontmatter":{},"headers":[],"relativePath":"guide/scheduler.md","filePath":"guide/scheduler.md","lastUpdated":1793030102000}'),t={name:"guide/scheduler.md"};function c(r,e,l,i,p,d){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="cron-scheduling" tabindex="-1">Cron Scheduling <a class="header-anchor" href="#cron-scheduling" aria-label="Permalink to &quot;Cron Scheduling&quot;">​</a></h1><p>The cron channel, <a href="/reference/channel-cron"><code>@chamvi/channel-cron</code></a>, fires the <code>cron.on()</code> subscriptions of your agents. Every replica registers the same channel; a lock in the shared store elects one replica per tick, and <code>engine.dispatch()</code> deduplicates a second firing of the same tick.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#E6DFDE;">npm </span><span style="color:#E7C58C;">install</span><span style="color:#E7C58C;"> @chamvi/channel-cron</span><span style="color:#E7C58C;"> @chamvi/core</span><span style="color:#E7C58C;"> --save</span></span></code></pre></div><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> engine = </span><span style="color:#FF7B84;">new</span><span style="color:#E6DFDE;"> Engine({</span></span>
<span class="line"><span style="color:#E6DFDE;">    store,</span></span>
<span class="line"><span style="color:#E6DFDE;">    agents,</span></span>
<span class="line"><span style="color:#958A8B;">    // every replica registers the same channel; a store lock fires each tick once</span></span>
<span class="line"><span style="color:#E6DFDE;">    channels: [cronChannel({ onError: (error, { agent, subscription }) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> console.error(</span><span style="color:#E7C58C;">&#39;[cron]&#39;</span><span style="color:#E6DFDE;">, agent, subscription, error) })],</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"><span style="color:#958A8B;">// recovers runs, then starts the channel</span></span>
<span class="line"><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> engine.start();</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E6DFDE;">process.once(</span><span style="color:#E7C58C;">&#39;SIGTERM&#39;</span><span style="color:#E6DFDE;">, </span><span style="color:#FF7B84;">async</span><span style="color:#E6DFDE;"> () </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> {</span></span>
<span class="line"><span style="color:#958A8B;">    // stops the channel first (no new ticks), then lets the runs in flight finish</span></span>
<span class="line"><span style="color:#FF7B84;">    await</span><span style="color:#E6DFDE;"> engine.drain({ timeoutMs: </span><span style="color:#E7C58C;">25_000</span><span style="color:#E6DFDE;"> });</span></span>
<span class="line"><span style="color:#E6DFDE;">    process.exit(</span><span style="color:#E7C58C;">0</span><span style="color:#E6DFDE;">);</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><p><code>cron.on(expression, options?)</code> validates the expression (cron-parser) and the timezone and throws <code>InvalidAgentDefinitionError</code> for one it refuses. <code>engine.start()</code> starts the channel after recovering runs: it creates one <a href="https://github.com/tada5hi/hubwire" target="_blank" rel="noreferrer">hubwire</a> scheduled component per cron subscription of the engine&#39;s agents, and a code agent&#39;s subscription it cannot use (an expression croner refuses) fails <code>engine.start()</code> with <code>InvalidAgentDefinitionError</code>, naming the agent and subscription; an <a href="/guide/agent-folders">agent folder</a>&#39;s goes to <code>onError</code> and leaves that agent unscheduled. The channel follows agents registered, replaced and removed at runtime. With <a href="/guide/app"><code>@chamvi/app</code></a>, <code>schedulerModule()</code> contributes the channel.</p><p>A second cron channel (<code>cronChannel({ name: &#39;cron-eu&#39; })</code>) has its own <code>on()</code>: its subscriptions fire only there, and <code>cron.on()</code> ones only on the channel named <code>cron</code>.</p><h2 id="one-dispatch-per-tick" tabindex="-1">One dispatch per tick <a class="header-anchor" href="#one-dispatch-per-tick" aria-label="Permalink to &quot;One dispatch per tick&quot;">​</a></h2><p>For a tick planned at <code>scheduledAt</code>, a replica:</p><ol><li>acquires the store lock <code>cron:&lt;agent&gt;:&lt;subscriptionId&gt;:&lt;scheduledAt ISO&gt;</code> for <code>lockTtlMs</code> (default 10 minutes). The key is never released, so a replica that fires the same tick late cannot win it again. The other replicas skip the tick.</li><li>applies the subscription&#39;s <a href="#overlap-policies">overlap policy</a>.</li><li>dispatches through the channel (envelope <code>channel</code> the channel&#39;s name, <code>trigger</code> the subscription id) with payload <code>options.payload ?? { scheduledAt }</code> (an ISO string) and the idempotency key <code>&lt;subscriptionId&gt;@&lt;scheduledAt ISO&gt;</code>. A subscription&#39;s own <code>idempotencyKey()</code> is ignored for cron.</li></ol><p>Starting or restarting a replica fires nothing: the first dispatch is at the next scheduled tick. Missed ticks are not caught up, neither a tick that falls into a restart nor one whose timer fires <code>lockTtlMs</code> or more late. A failing lock store, overlap check or dispatch reaches <code>onError(error, { agent, subscription })</code>, and the next tick runs normally.</p><h2 id="overlap-policies" tabindex="-1">Overlap policies <a class="header-anchor" href="#overlap-policies" aria-label="Permalink to &quot;Overlap policies&quot;">​</a></h2><p>&quot;Active&quot; means a run of the same subscription in <code>queued</code>, <code>running</code>, <code>waiting</code> or <code>interrupted</code>.</p><table tabindex="0"><thead><tr><th>Policy</th><th>The tick is skipped when</th><th>Default <code>concurrencyKey</code></th></tr></thead><tbody><tr><td><code>skip</code> (default)</td><td>any run of the subscription is active</td><td>the subscription id</td></tr><tr><td><code>queue-one</code></td><td>a run of the subscription is still <code>queued</code></td><td>the subscription id</td></tr><tr><td><code>allow</code></td><td>never</td><td>none</td></tr></tbody></table><p>The default concurrency key makes <code>queue-one</code> wait: the engine starts one run per agent and key at a time (see <a href="/guide/concurrency">Concurrency</a>), so the queued run starts when the active one settles. It also makes a race harmless: when a tick checks while the previous tick&#39;s dispatch is still in flight, the second run waits instead of running alongside. A <code>concurrencyKey(payload)</code> on the subscription wins over the default.</p><h2 id="timezones" tabindex="-1">Timezones <a class="header-anchor" href="#timezones" aria-label="Permalink to &quot;Timezones&quot;">​</a></h2><p><code>cron.on(expression, { timezone })</code> takes an IANA zone; without one, the process&#39;s local zone applies. A local time that occurs twice at the fall-back change fires once, at its first occurrence. A local time the spring-forward change skips fires once, an hour later in local time.</p><h2 id="shutdown" tabindex="-1">Shutdown <a class="header-anchor" href="#shutdown" aria-label="Permalink to &quot;Shutdown&quot;">​</a></h2><p><code>engine.drain()</code> (and <code>engine.stop()</code>) stop every channel first: the cron channel unschedules its subscriptions and waits for ticks in flight, then the drain waits for the runs. See <a href="/guide/recovery#drain">Cancel, Drain &amp; Recovery</a>.</p><h2 id="one-shot-jobs" tabindex="-1">One-shot jobs <a class="header-anchor" href="#one-shot-jobs" aria-label="Permalink to &quot;One-shot jobs&quot;">​</a></h2><p><code>runJob()</code> fires one cron subscription once and waits for its run, for a Kubernetes CronJob instead of a long-lived replica:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#958A8B;">// a Kubernetes CronJob: fire the agent&#39;s cron subscription once and exit with its outcome</span></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> engine = </span><span style="color:#FF7B84;">new</span><span style="color:#E6DFDE;"> Engine({</span></span>
<span class="line"><span style="color:#E6DFDE;">    store,</span></span>
<span class="line"><span style="color:#E6DFDE;">    agents: [agent],</span></span>
<span class="line"><span style="color:#958A8B;">    // the engine must hold the channel; runJob starts it with start({ channels: false })</span></span>
<span class="line"><span style="color:#E6DFDE;">    channels: [cronChannel()],</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> { status, exitCode } = </span><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> runJob({</span></span>
<span class="line"><span style="color:#E6DFDE;">    engine,</span></span>
<span class="line"><span style="color:#E6DFDE;">    agent,</span></span>
<span class="line"><span style="color:#E6DFDE;">    drainTimeoutMs: </span><span style="color:#E7C58C;">120_000</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"><span style="color:#E6DFDE;">console.log(</span><span style="color:#E7C58C;">&#39;cron run&#39;</span><span style="color:#E6DFDE;">, status);</span></span>
<span class="line"><span style="color:#E6DFDE;">process.exitCode = exitCode;</span></span></code></pre></div><p>The tick is dispatched at the current time (the overlap policy applies). The engine is then started with <code>start({ channels: false })</code>, so a job never starts cron schedules or any other channel, and runs one approval tick even when the tick is skipped, so leftovers of earlier jobs make progress: a run whose pod was killed is recovered, an interrupted or answered run is executed, and an approval past its timeout is denied. The job returns when the run is <code>completed</code> (exit code 0), <code>waiting</code> for an approval (0, the pod is not held), <code>queued</code> behind a run of the same subscription that waits for an approval (0, under <code>queue-one</code>), <code>failed</code> or <code>cancelled</code> (1), or <code>skipped</code> by the overlap policy (0). It polls <code>engine.getRun</code> every <code>pollMs</code>, so a run finished by another replica also ends the job. It never calls <code>process.exit</code>. The engine must hold the subscription&#39;s cron channel.</p><div class="warning custom-block"><p class="custom-block-title">A job runs a full engine</p><p><code>engine.start()</code> recovers and executes every queued run of every agent in the shared store, not only the cron run, and the final <code>drain()</code> interrupts whatever still runs after <code>drainTimeoutMs</code>. <code>runJob</code> waits only for its own run, so a leftover run is finished by a long-lived replica or by a later job pod, within that pod&#39;s <code>drainTimeoutMs</code>. Size <code>drainTimeoutMs</code> to the job&#39;s runs, and prefer a long-lived deployment with <code>cronChannel()</code> when runs are long.</p></div>`,23)])])}const y=n(t,[["render",c]]);export{u as __pageData,y as default};
